insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 15, 'Biologia', 'A ovinocultura tem um importante papel econômico, seja na produção de lã, carne ou outros insumos utilizados pelo homem. Na produção animal, a escolha dos melhores animais e o cruzamento entre os mesmos é a base para a obtenção de genótipos específicos que incrementam a média de produção pelos produtores. Um casal de ovinos, em que ambos os genitores possuem genótipo AaBbCc, foi intercruzado. Considerando-se que os genes em questão segregam-se independentemente, qual a probabilidade de o casal gerar um filhote com o mesmo genótipo que os seus?', 'Redação adaptada para estudo; numeração e ordem das alternativas preservadas. Textos de apoio resumidos. Consulte a questão e os textos integrais no caderno oficial. Explicação autoral, não publicada pela banca. As 20 questões objetivas são comuns às quatro áreas; o link abre o caderno de Humanas. As discursivas não integram este cadastro.', null, '["1/2", "1/4", "1/8", "1/16", "1/32"]'::jsonb, 'C', 'Gabarito oficial: C. Em Aa×Aa a probabilidade de Aa é 1/2. Para três genes independentes, a probabilidade de AaBbCc é (1/2)³ = 1/8.' from public.exams where slug='pism-iii-2024-dia-1'

