insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 16, 'Matemática', 'Considere p(x)=x²+x−6, q(x)=x²+x/2−1/2 e r(x)=p(x)q(x). A soma dos coeficientes de r é C e o produto de suas raízes é P. Qual é C+P?', 'Redação adaptada para estudo; numeração e ordem das alternativas preservadas. Textos de apoio resumidos. Consulte a questão e os textos integrais no caderno oficial. Explicação autoral, não publicada pela banca. As 20 questões objetivas são comuns às quatro áreas; o link abre o caderno de Humanas. As discursivas não integram este cadastro.', null, '["−8", "−6", "−1", "0", "7"]'::jsonb, 'C', 'Gabarito oficial: C. A soma dos coeficientes é C=r(1)=p(1)q(1)=−4. O produto das quatro raízes do polinômio mônico é P=r(0)=p(0)q(0)=3. Logo C+P=−1.' from public.exams where slug='pism-iii-2024-dia-1'

