insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 17, 'Matemática', 'Se a>3 e (x,y) resolve o sistema −x+y=a e −2x+y=3, a que região do plano pertence esse ponto?', 'Redação adaptada para estudo; numeração e ordem das alternativas preservadas. Textos de apoio resumidos. Consulte a questão e os textos integrais no caderno oficial. Explicação autoral, não publicada pela banca. As 20 questões objetivas são comuns às quatro áreas; o link abre o caderno de Humanas. As discursivas não integram este cadastro.', null, '["Eixo x.", "Eixo y.", "Primeiro quadrante, x≠0 e y≠0.", "Segundo quadrante, x≠0 e y≠0.", "Terceiro quadrante, x≠0 e y≠0."]'::jsonb, 'C', 'Gabarito oficial: C. Subtraindo as equações, x = a−3 e y = 2a−3. Para a>3, ambas as coordenadas são positivas, situando a solução no primeiro quadrante.' from public.exams where slug='pism-iii-2024-dia-1'

on conflict (exam_id,number) do update set subject=excluded.subject, text=excluded.text, support=excluded.support, support_image=excluded.support_image, options=excluded.options, answer=excluded.answer, explanation=excluded.explanation;

insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 18, 'Matemática', 'Bernardo trabalha como vendedor, de segunda a sexta, na loja Passarinhos. Ele recebeu 5 camisas de uniforme com cores distintas para usar no trabalho. Ao longo da semana, quando ele usa uma camisa, não pode usála no dia seguinte, pois ela deve ser lavada e seca, mas pode usá-la novamente em outro dia. Em uma semana, começando com todas as camisas lavadas e secas, Bernardo pegará, aleatoriamente, uma camisa dentre as disponíveis para uso. Qual é a probabilidade de que ele trabalhe todos os 5 dias com camisas de cores diferentes?', 'Redação adaptada para estudo; numeração e ordem das alternativas preservadas. Textos de apoio resumidos. Consulte a questão e os textos integrais no caderno oficial. Explicação autoral, não publicada pela banca. As 20 questões objetivas são comuns às quatro áreas; o link abre o caderno de Humanas. As discursivas não integram este cadastro.', null, '["1/5⁵", "1/(5·4⁴)", "1/5!", "3/2⁵", "5/4!"]'::jsonb, 'D', 'Gabarito oficial: D. Há 5·4⁴ sequências possíveis sem repetir a cor em dias consecutivos. As sequências com todas as cores distintas são 5!. A probabilidade é 120/1280 = 3/32.' from public.exams where slug='pism-iii-2024-dia-1'

