insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 19, 'Matemática', 'A=(1,3) e B=(7,12). Dois pontos C e D dividem AB em três segmentos iguais. Quais são suas coordenadas?', 'Redação adaptada para estudo; numeração e ordem das alternativas preservadas. Textos de apoio resumidos. Consulte a questão e os textos integrais no caderno oficial. Explicação autoral, não publicada pela banca. As 20 questões objetivas são comuns às quatro áreas; o link abre o caderno de Humanas. As discursivas não integram este cadastro.', null, '["(2,3) e (4,6)", "(4,6) e (7,9)", "(2,3) e (5,6)", "(3,0) e (0,9)", "(3,6) e (5,9)"]'::jsonb, 'E', 'Gabarito oficial: E. Os pontos trisseccionam o vetor B−A = (6,9). Somando um e dois terços desse vetor a A, obtemos (3,6) e (5,9).' from public.exams where slug='pism-iii-2024-dia-1'

