insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 20, 'Matemática', 'Maria possui um estojo contendo 8 peças de bijuterias, sendo 2 em forma de quadrado, 2 em forma de triângulo, 2 em forma de disco e 2 em forma de estrela. Peças de mesma forma são idênticas. De quantas maneiras distintas Maria pode escolher 6 dessas peças de modo que tenha pelo menos uma de cada forma?', 'Redação adaptada para estudo; numeração e ordem das alternativas preservadas. Textos de apoio resumidos. Consulte a questão e os textos integrais no caderno oficial. Explicação autoral, não publicada pela banca. As 20 questões objetivas são comuns às quatro áreas; o link abre o caderno de Humanas. As discursivas não integram este cadastro.', null, '["6", "10", "12", "24", "30"]'::jsonb, 'A', 'Gabarito oficial: A. Selecionar seis peças dentre duas de cada uma de quatro formas, incluindo todas as formas, exige duas formas com duas peças e duas com uma peça. As formas duplicadas podem ser escolhidas de C(4,2) = 6 maneiras.' from public.exams where slug='pism-iii-2024-dia-1'

