insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 1, 'Física', 'O campo magnético da Terra protege nosso planeta dos raios cósmicos, permitindo a existência de vida. Contudo, pesquisas recentes mostram a possibilidade de alteração na sua intensidade e mudança na sua orientação no espaço. Em relação à origem mais provável do campo magnético da Terra, temos que ele é produzido', 'Redação adaptada para estudo; numeração e ordem das alternativas preservadas. Textos de apoio resumidos. Consulte a questão e os textos integrais no caderno oficial. Explicação autoral, não publicada pela banca. As 20 questões objetivas são comuns às quatro áreas; o link abre o caderno de Humanas. As discursivas não integram este cadastro.', null, '["como resultado do movimento de translação da Terra em torno do Sol.", "pelo movimento das cargas elétricas resultantes das colisões dos raios cósmicos com a atmosfera terrestre.", "pelo movimento de cargas elétricas em sua superfície.", "por um grande ímã permanente de ferro que há no centro da Terra.", "por cargas elétricas em movimento em seu interior."]'::jsonb, 'E', 'Gabarito oficial: E. O campo magnético terrestre é explicado pelo geodínamo: movimento de material condutor no interior da Terra, associado a cargas elétricas em movimento.' from public.exams where slug='pism-iii-2024-dia-2'

