insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 2, 'Física', 'O galvanômetro é um aparelho capaz de medir pequenas correntes elétricas que passam por ele. Entretanto, as correntes elétricas em circuitos cotidianos geralmente são muito maiores do que o galvanômetro suporta diretamente. Modificações podem ser feitas no galvanômetro com a associação de um resistor, de forma apropriada, para permitir fazê-lo funcionar como um voltímetro ou como um amperímetro. Este resistor pode ter resistência grande ou pequena, relativamente à resistência interna do galvanômetro. Assinale a alternativa que representa a associação apropriada do resistor com o galvanômetro, a partir do funcionamento CORRETO do voltímetro e do amperímetro.', 'Redação adaptada para estudo; numeração e ordem das alternativas preservadas. Textos de apoio resumidos. Consulte a questão e os textos integrais no caderno oficial. Explicação autoral, não publicada pela banca. As 20 questões objetivas são comuns às quatro áreas; o link abre o caderno de Humanas. As discursivas não integram este cadastro.', null, '["Amperímetro é um galvanômetro com uma grande resistência em paralelo.", "Amperímetro é um galvanômetro com uma grande resistência em série.", "Amperímetro é um galvanômetro com uma pequena resistência em série.", "Voltímetro é um galvanômetro com uma grande resistência em série.", "Voltímetro é um galvanômetro com uma grande resistência em paralelo."]'::jsonb, 'D', 'Gabarito oficial: D. O voltímetro deve ter resistência elevada para reduzir a corrente que retira do circuito. Constrói-se adicionando grande resistência em série ao galvanômetro.' from public.exams where slug='pism-iii-2024-dia-2'

