insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 3, 'Física', 'Na eletrostática, objetos neutros podem ser eletrizados por atrito, por contato e por indução, e podem ser classificados simplificadamente como condutores ou isolantes. Em relação à eletrização de objetos, assinale a afirmativa CORRETA.', 'Redação adaptada para estudo; numeração e ordem das alternativas preservadas. Textos de apoio resumidos. Consulte a questão e os textos integrais no caderno oficial. Explicação autoral, não publicada pela banca. As 20 questões objetivas são comuns às quatro áreas; o link abre o caderno de Humanas. As discursivas não integram este cadastro.', null, '["Ao ser carregado por atrito, um objeto neutro ficará sempre com o mesmo sinal de carga elétrica, devido ao material do qual ele é feito.", "As cargas que dois objetos neutros adquirem, após o atrito entre ambos, dependem da facilidade de um ceder elétrons ao outro.", "Quando dois objetos condutores neutros, de materiais diferentes, são atritados entre si, ambos podem ficar com cargas elétricas de mesmo sinal, pois possuem elétrons livres.", "Somente objetos condutores carregados podem interagir por indução, pois necessitam de cargas livres.", "Somente objetos isolantes podem ser carregados por contato com outro objeto carregado."]'::jsonb, 'B', 'Gabarito oficial: B. A eletrização por atrito transfere elétrons entre os materiais. Os sinais adquiridos dependem da facilidade relativa de doar e receber elétrons.' from public.exams where slug='pism-iii-2024-dia-2'

