insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 4, 'Física', 'Uma nave de comprimento próprio 6 m aproxima-se da Terra a 0,6c. Outra nave, a 0,8c, apresenta ao observador terrestre o dobro do comprimento observado da primeira. Usando L=L₀√(1−v²/c²), qual o comprimento próprio da segunda?', 'Redação adaptada para estudo; numeração e ordem das alternativas preservadas. Textos de apoio resumidos. Consulte a questão e os textos integrais no caderno oficial. Explicação autoral, não publicada pela banca. As 20 questões objetivas são comuns às quatro áreas; o link abre o caderno de Humanas. As discursivas não integram este cadastro.', null, '["4,8 m", "8,0 m", "9,6 m", "12,0 m", "16,0 m"]'::jsonb, 'E', 'Gabarito oficial: E. A primeira nave é observada com L = 6√(1−0,6²) = 4,8 m. A segunda tem comprimento observado 9,6 m e fator √(1−0,8²) = 0,6. Seu comprimento próprio é 9,6/0,6 = 16 m.' from public.exams where slug='pism-iii-2024-dia-2'

on conflict (exam_id,number) do update set subject=excluded.subject, text=excluded.text, support=excluded.support, support_image=excluded.support_image, options=excluded.options, answer=excluded.answer, explanation=excluded.explanation;

insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 5, 'Física', 'Considere as seguintes afirmações relacionadas ao tema da dualidade onda-partícula: I – Elétrons podem difratar-se. II – Fótons não têm massa de repouso, portanto, sua energia é nula. III – Os efeitos Compton e fotoelétrico podem ser compreendidos como manifestações da natureza corpuscular da onda eletromagnética. Assinale a alternativa CORRETA a respeito dessas afirmações.', 'Redação adaptada para estudo; numeração e ordem das alternativas preservadas. Textos de apoio resumidos. Consulte a questão e os textos integrais no caderno oficial. Explicação autoral, não publicada pela banca. As 20 questões objetivas são comuns às quatro áreas; o link abre o caderno de Humanas. As discursivas não integram este cadastro.', null, '["Somente I é verdadeira.", "Somente II é verdadeira.", "Somente III é verdadeira.", "Somente I e III são verdadeiras.", "I, II e III são verdadeiras."]'::jsonb, 'D', 'Gabarito oficial: D. Elétrons apresentam difração, e os efeitos Compton e fotoelétrico evidenciam o comportamento corpuscular da luz. Fótons têm energia E = hf, mesmo sem massa de repouso.' from public.exams where slug='pism-iii-2024-dia-2'

