insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 6, 'Química', 'Uma solução saturada de NaCl evapora à temperatura constante e estabelece o equilíbrio NaCl(s) ⇌ Na⁺(aq)+Cl⁻(aq). Qual afirmativa sobre esse processo é INCORRETA?', 'Redação adaptada para estudo; numeração e ordem das alternativas preservadas. Textos de apoio resumidos. Consulte a questão e os textos integrais no caderno oficial. Explicação autoral, não publicada pela banca. As 20 questões objetivas são comuns às quatro áreas; o link abre o caderno de Humanas. As discursivas não integram este cadastro.', null, '["A dupla seta indica que a dissolução do cloreto de sódio sólido e a recristalização dos íons solvatados ocorrem durante o equilíbrio químico.", "A saturação da solução ocorre quando os íons sódio e cloreto atingem concentração máxima, nas condições descritas.", "A solvatação do cloreto de sódio ocorre quando os íons sódio e cloreto ficam ligados e envoltos por moléculas de água.", "Na medida em que a água evapora ocorre o deslocamento do equilíbrio, aumentando a massa do cloreto de sódio sólido.", "O equilíbrio químico é sempre um processo dinâmico, isto é, a reação ocorre nos dois sentidos, mesmo que a temperatura fique constante."]'::jsonb, 'C', 'Gabarito oficial: C. A solvatação separa os íons do retículo cristalino e envolve cada um por moléculas de água. A alternativa C é incorreta ao afirmar que sódio e cloreto ficam ligados entre si na solução.' from public.exams where slug='pism-iii-2024-dia-2'

