insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 7, 'Química', 'Carboidratos, de fórmula geral aproximada (CH₂O)n, participam da estrutura e do metabolismo celular. Qual afirmativa é INCORRETA?', 'Redação adaptada para estudo; numeração e ordem das alternativas preservadas. Textos de apoio resumidos. Consulte a questão e os textos integrais no caderno oficial. Explicação autoral, não publicada pela banca. As 20 questões objetivas são comuns às quatro áreas; o link abre o caderno de Humanas. As discursivas não integram este cadastro.', null, '["A celulose é um carboidrato, sendo o principal responsável pela estruturação das células vegetais.", "A glicose, presente no sangue humano, sofre oxidação para produção de energia necessária ao metabolismo.", "A respiração celular é a conversão da glicose em gás carbônico e água e ocorre nas células de animais, mas não das plantas.", "A sacarose é o principal carboidrato obtido da cana-de-açúcar e é formado pela ligação química entre a glicose e a frutose.", "O amido é um polímero de glicose, que pode ser convertido em energia quando necessário."]'::jsonb, 'C', 'Gabarito oficial: C. Plantas também realizam respiração celular, oxidando compostos orgânicos para obter energia. A alternativa C é incorreta ao restringir esse processo aos animais.' from public.exams where slug='pism-iii-2024-dia-2'

