insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 8, 'Química', 'A panela de pressão é comumente empregada para agilizar o cozimento de alimentos. Quando levada ao fogo faz com que a temperatura de ebulição da água se eleve acima de 100 oC, devido ao aumento da pressão interna. Com base na teoria das colisões, indique a resposta CORRETA.', 'Redação adaptada para estudo; numeração e ordem das alternativas preservadas. Textos de apoio resumidos. Consulte a questão e os textos integrais no caderno oficial. Explicação autoral, não publicada pela banca. As 20 questões objetivas são comuns às quatro áreas; o link abre o caderno de Humanas. As discursivas não integram este cadastro.', null, '["Com o aumento da pressão dentro da panela, as colisões entre as moléculas e íons diminuem fazendo com que o processo de cozimento seja mais rápido.", "A pressão interna da panela diminui a concentração de moléculas e íons aumentando a velocidade das reações químicas envolvidas durante o cozimento.", "A superfície de contato dos alimentos durante o cozimento diminui devido à elevação da pressão aumentando a velocidade de cozimento dos alimentos.", "A velocidade de cozimento na panela de pressão é maior, pois a energia cinética média das moléculas e íons é maior.", "O aumento da temperatura de ebulição não altera a energia cinética média das moléculas, acelerando o processo de cozimento."]'::jsonb, 'D', 'Gabarito oficial: D. A maior temperatura aumenta a energia cinética média e a proporção de colisões eficazes, acelerando as transformações que cozinham os alimentos.' from public.exams where slug='pism-iii-2024-dia-2'

