insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 9, 'Química', 'Frações de petróleo incluem GLP (C₁–C₄), gasolina (C₅–C₁₂), querosene (C₁₀–C₁₆), diesel (C₁₄–C₂₀) e óleo lubrificante (C₂₀–C₅₀). Qual sequência é compatível com a destilação fracionada?', 'Redação adaptada para estudo; numeração e ordem das alternativas preservadas. Textos de apoio resumidos. Consulte a questão e os textos integrais no caderno oficial. Explicação autoral, não publicada pela banca. As 20 questões objetivas são comuns às quatro áreas; o link abre o caderno de Humanas. As discursivas não integram este cadastro.', null, '["a gasolina é destilada depois do óleo diesel.", "o GLP é a última fração a ser destilada.", "o óleo diesel é a fração destilada antes do querosene.", "o óleo lubrificante constitui a fração destilada antes da gasolina.", "o querosene constitui a fração destilada após a gasolina."]'::jsonb, 'E', 'Gabarito oficial: E. Na destilação fracionada, as frações são separadas segundo suas faixas de ebulição. O querosene tem cadeias maiores e é separado depois da gasolina.' from public.exams where slug='pism-iii-2024-dia-2'

