insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 10, 'Química', 'Na limpeza eletrolítica de piscinas: i — 2Cl⁻ → Cl₂+2e⁻; ii — 2H₂O+2e⁻ → H₂+2OH⁻; iii — Cl₂+2OH⁻ → Cl⁻+ClO⁻+H₂O. Analise: I — formam-se espécies de cloro oxidadas e reduzidas; II — Cl₂ se forma no cátodo; III — ClO⁻ se forma mesmo sem OH⁻; IV — são necessários cátodo e ânodo. Quais são corretas?', 'Redação adaptada para estudo; numeração e ordem das alternativas preservadas. Textos de apoio resumidos. Consulte a questão e os textos integrais no caderno oficial. Explicação autoral, não publicada pela banca. As 20 questões objetivas são comuns às quatro áreas; o link abre o caderno de Humanas. As discursivas não integram este cadastro.', null, '["(I) e (II)", "(II) e (III)", "(III) e (IV)", "(I) e (IV)", "(II) e (IV)"]'::jsonb, 'D', 'Gabarito oficial: D. Cloro pode ser oxidado e reduzido nas reações, e a eletrólise exige ânodo e cátodo: I e IV corretas. Cl₂ é produzido por oxidação no ânodo; a formação de hipoclorito representada depende de OH⁻.' from public.exams where slug='pism-iii-2024-dia-2'

