insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 11, 'Geografia', 'A figura abaixo apresenta os cabos submarinos instalados para permitir a acessibilidade à internet. Considerando a atual integração dos países por redes . materiais e imateriais, assinale a alternativa CORRETA:', 'Redação adaptada para estudo; numeração e ordem das alternativas preservadas. Textos de apoio resumidos. Consulte a questão e os textos integrais no caderno oficial. Explicação autoral, não publicada pela banca. As 20 questões objetivas são comuns às quatro áreas; o link abre o caderno de Humanas. As discursivas não integram este cadastro.', '/pism-iii-2024-dia-2-questao-11.png', '["A rede é apenas de transporte de mercadorias.", "Cabos constituem uma rede material para fluxos imateriais de informação e comunicação.", "Redes materiais e imateriais equilibram automaticamente as relações internacionais.", "A baixa conexão entre América Latina e África é irrelevante, pois todos os centros estão no Atlântico Norte.", "As rotas atuais correspondem às antigas rotas de tráfico entre Estados Unidos e África."]'::jsonb, 'B', 'Gabarito oficial: B. Os cabos são infraestrutura material que permite fluxos imateriais de informações. Sua distribuição desigual expressa a organização econômica e política mundial.' from public.exams where slug='pism-iii-2024-dia-2'

