insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 13, 'Geografia', 'Em julho de 2023, lideranças de Argentina e Brasil discutiram assimetrias nas negociações Mercosul–União Europeia, com receio de manter a região como fornecedora de produtos primários. Qual afirmação corresponde a esse debate?', 'Redação adaptada para estudo; numeração e ordem das alternativas preservadas. Textos de apoio resumidos. Consulte a questão e os textos integrais no caderno oficial. Explicação autoral, não publicada pela banca. As 20 questões objetivas são comuns às quatro áreas; o link abre o caderno de Humanas. As discursivas não integram este cadastro.', null, '["A defesa da integração comercial, por ambos os presidentes, faz referência ao novo passo a ser dado pelo Mercosul com o intuito de reduzir as barreiras entre cidadãos sul-americanos.", "A possível condenação dos países do Mercosul a serem apenas fornecedores se deve à manutenção de regras protecionistas, por parte de alguns países da UE, que exporiam pequenas e médias empresas sul-americanas.", "A recente negociação entre Mercosul e UE tende a intensificar as mudanças na ordem mundial ao fortalecer as indústrias sul-americanas por meio da ampliação da exportação de produtos de maior valor agregado.", "O presidente da Argentina, ao se referir à importância da integração comercial, demonstra sua discordância com o Chile, que tem buscado manter negociações autônomas mesmo sendo um membro do Mercosul.", "A questão das compras governamentais, sobre a qual há concordância entre os presidentes do Brasil e da Argentina, refere-se à constituição de uma nova moeda para a América do Sul que substituiria às moedas nacionais."]'::jsonb, 'B', 'Gabarito oficial: B. A assimetria discutida envolve protecionismo e regras comerciais que podem manter países sul-americanos como fornecedores de produtos primários e expor empresas locais.' from public.exams where slug='pism-iii-2024-dia-2'

