insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 15, 'Geografia', 'Duas reportagens tratam de cooperação com a República do Congo e a República Democrática do Congo e de migração na fronteira entre Tunísia e Líbia. Em que regiões africanas se localizam, respectivamente, os países desses dois casos?', 'Redação adaptada para estudo; numeração e ordem das alternativas preservadas. Textos de apoio resumidos. Consulte a questão e os textos integrais no caderno oficial. Explicação autoral, não publicada pela banca. As 20 questões objetivas são comuns às quatro áreas; o link abre o caderno de Humanas. As discursivas não integram este cadastro.

Reportagens resumidas. Use a regionalização africana em cinco regiões adotada no caderno.', null, '["1) Magreb | 2) Sahel", "1) Sahel | 2) África Setentrional", "1) África Meridional | 2) Magreb", "1) África Ocidental | 2) África Oriental", "1) África Central | 2) África Setentrional"]'::jsonb, 'E', 'Gabarito oficial: E. República do Congo e República Democrática do Congo pertencem à África Central; Tunísia e Líbia, à África Setentrional.' from public.exams where slug='pism-iii-2024-dia-2'

