insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 16, 'História', 'Um estudo sobre fascismo espanhol e uma notícia sobre racismo contra Vinicius Junior em 2023 permitem relacionar passado e presente. O que essa comparação evidencia?', 'Redação adaptada para estudo; numeração e ordem das alternativas preservadas. Textos de apoio resumidos. Consulte a questão e os textos integrais no caderno oficial. Explicação autoral, não publicada pela banca. As 20 questões objetivas são comuns às quatro áreas; o link abre o caderno de Humanas. As discursivas não integram este cadastro.

O estudo aborda vínculos entre fascismo espanhol e nazismo. A notícia descreve uma torcida organizada vinculada a referências ultranacionalistas e racistas. Leia os textos originais no caderno.', null, '["foi juridicamente estabelecida no contexto de institucionalização do regime fascista espanhol no final do século XIX.", "foi um fenômeno em ascensão nos anos finais do século XX, sem relação direta com o fascismo espanhol.", "não possui relação com o fascismo espanhol porque esse regime se diferenciava do nazismo no tocante à questão racial.", "possui vinculação com o contexto de emergência do fascismo espanhol, com repercussão em práticas sociais atuais.", "é explicada pela aproximação recente entre torcidas organizadas de times espanhóis e de times alemães que compartilham ideais fascistas."]'::jsonb, 'D', 'Gabarito oficial: D. Os textos relacionam o fascismo espanhol histórico a práticas racistas contemporâneas, evidenciando continuidade de discursos e sociabilidades autoritárias.' from public.exams where slug='pism-iii-2024-dia-2'

