insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 17, 'História', 'Em 1928, o Bloco Operário e Camponês elegeu representantes. Um jornal comunista defendia a participação eleitoral como nova frente, somada à mobilização de massas. Que posição o texto expressa?', 'Redação adaptada para estudo; numeração e ordem das alternativas preservadas. Textos de apoio resumidos. Consulte a questão e os textos integrais no caderno oficial. Explicação autoral, não publicada pela banca. As 20 questões objetivas são comuns às quatro áreas; o link abre o caderno de Humanas. As discursivas não integram este cadastro.

Resumo do texto e da imagem histórica do caderno.', null, '["a rejeição dos Anarquistas em relação a procedimentos e instituições político-parlamentares típicos da democracia liberal.", "a crítica das oligarquias ao sistema eleitoral vigente, em que só votavam homens alfabetizados e maiores de 21 anos.", "a visão dos Socialistas no sentido de defender o processo eleitoral como principal meio de conquistar direitos sociais.", "a defesa de uma reforma imediata do sistema eleitoral da Primeira República, visando permitir a candidatura de membros da classe trabalhadora.", "a posição dos Comunistas em defesa da participação no processo eleitoral, compreendido como um espaço de luta política dentre outros."]'::jsonb, 'E', 'Gabarito oficial: E. Os comunistas tratam a disputa eleitoral como uma das frentes da luta política, articulada a outras formas de mobilização, e não como caminho exclusivo.' from public.exams where slug='pism-iii-2024-dia-2'

