insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 18, 'História', 'Uma capa de Superman publicada durante a Segunda Guerra mostra o herói enfrentando líderes do Eixo. Qual interpretação explica seu uso político?', 'Redação adaptada para estudo; numeração e ordem das alternativas preservadas. Textos de apoio resumidos. Consulte a questão e os textos integrais no caderno oficial. Explicação autoral, não publicada pela banca. As 20 questões objetivas são comuns às quatro áreas; o link abre o caderno de Humanas. As discursivas não integram este cadastro.

Descrição da capa de Superman nº 17. Consulte a imagem original no caderno oficial.', null, '["Os EUA participaram da Segunda Guerra Mundial, principalmente a partir da política cultural, por isso, filmes, desenhos animados e história em quadrinhos foram utilizados à exaustão.", "A utilização das histórias em quadrinhos tinha como objetivo primordial o alistamento de soldados, assim como justificar a presença de mulheres jovens nos campos de batalha no território europeu.", "A capa de Superman reforçava o uso da indústria cultural, como forma de representar a participação dos EUA na Segunda Guerra Mundial, e valorizar a presença americana como solucionadora do conflito.", "A participação dos EUA na Segunda Guerra Mundial não foi consenso entre as forças aliadas, por essa razão, a indústria cultural foi um instrumento para justificar a necessidade da incursão militar.", "A entrada dos EUA na Segunda Guerra Mundial representou o momento de criação da indústria cultural, sendo que filmes, histórias em quadrinhos e desenhos animados surgiram no contexto da guerra."]'::jsonb, 'C', 'Gabarito oficial: C. A representação de Superman enfrentando líderes do Eixo associa entretenimento à propaganda de guerra e valoriza a intervenção americana.' from public.exams where slug='pism-iii-2024-dia-2'

