insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 19, 'História', 'Um texto de Marcelo Ridenti descreve investimentos estatais em telecomunicações, Embratel e instituições culturais, acompanhados de expansão privada e controle político. A que período se refere?', 'Redação adaptada para estudo; numeração e ordem das alternativas preservadas. Textos de apoio resumidos. Consulte a questão e os textos integrais no caderno oficial. Explicação autoral, não publicada pela banca. As 20 questões objetivas são comuns às quatro áreas; o link abre o caderno de Humanas. As discursivas não integram este cadastro.', null, '["Primeira República, quando artistas e intelectuais ligados ao movimento modernista e antropofágico defenderam a ideia de aglutinação e integração das culturas e a “devoração crítica das influências culturais” estrangeiras.", "Contrução do Estado Novo, quando intelectuais se inseriram na organização político-ideológica do Estado, participando da construção do projeto político-pedagógico de implementação, popularização e difusão da ideologia do regime.", "Aos chamados Anos Dourados, quando as políticas do governo de Juscelino Kubitschek, baseadas no nascionalismo e no desenvolvimentismo, deram suporte a projetos culturais de caráter inclusivo e universalista.", "Ditadura Militar, quando, paralelamente à censura, observa-se um esforço governamental modernizador nas áreas de comunicação e cultura, incentivando o investimento privado e a ação estatal direcionada, inclusive, a integração nacional.", "Redemocratização, quando, apesar da criação de órgãos de incentivo à cultura, como a ANCINE, verifica-se um declínio da participação estatal na cultura e um incremento da propaganda governamental como meio de assegurar a segurança nacional."]'::jsonb, 'D', 'Gabarito oficial: D. Na ditadura militar, a censura coexistiu com investimentos em telecomunicações e instituições culturais, voltados à modernização e à integração nacional.' from public.exams where slug='pism-iii-2024-dia-2'

