insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 11, 'Biologia', 'O Pantanal sofreu incêndios intensos em 2023. A reportagem citada aponta a ação humana no início de muitos focos e condições ambientais favoráveis à propagação. Qual afirmativa é correta?', 'Redação adaptada para estudo; numeração e ordem das alternativas preservadas. Textos de apoio resumidos. Consulte a questão e os textos integrais no caderno oficial. Explicação autoral, não publicada pela banca. As 20 questões objetivas são comuns às quatro áreas; o link abre o caderno de Humanas. As discursivas não integram este cadastro.', null, '["No pantanal existem turfeiras que são microambientes onde plantas crescem sobre outras plantas e formam espessa camada orgânica onde ocorre o conhecido fogo subterrâneo. A persistência desse fogo possui correlação com a intensidade das chuvas na região.", "Existe, na região do Pantanal, suficiente número de brigadas bem treinadas para combater o fogo, bem como grande investimento em prevenção dos incêndios.", "As áreas destinadas ao cultivo agrícola e à pecuária são comuns no Pantanal, onde são frequentes práticas que utilizam o fogo para preparar áreas para novos plantios e uso na produção animal, o que pode ser uma causa importante dos incêndios.", "As descargas elétricas causadas pelas chuvas em regiões de vegetação seca no Pantanal não constituem condição favorável ao surgimento de incêndio.", "O atraso na chegada das chuvas somado à forte onda de calor na região tornou o ambiente propício para que os focos de incêndio se ampliem na região do Pantanal nos períodos de estiagem atípica dos últimos anos."]'::jsonb, 'C/E', 'Gabarito oficial: C/E. O gabarito após recursos aceita C e E. A ação humana pode iniciar incêndios, enquanto seca e calor favorecem sua propagação. As duas alternativas correspondem a fatores relevantes; a correção deve aceitar ambas.' from public.exams where slug='pism-iii-2025-dia-1'

