insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 12, 'Biologia', 'Mudanças climáticas podem deslocar espécies, alterar interações e causar extinções locais. Considerando habitat, nicho e adaptação, qual afirmativa é correta?', 'Redação adaptada para estudo; numeração e ordem das alternativas preservadas. Textos de apoio resumidos. Consulte a questão e os textos integrais no caderno oficial. Explicação autoral, não publicada pela banca. As 20 questões objetivas são comuns às quatro áreas; o link abre o caderno de Humanas. As discursivas não integram este cadastro.', null, '["as interações ecológicas correspondem a uma parte importante do nicho ecológico e podem determinar a sobrevivência de uma espécie em uma nova localidade.", "as mutações no DNA, relacionadas aos processos adaptativos, somente ocorrerem quando uma espécie enfrenta mudanças nos fatores físicos e biológicos do ambiente, como os provocados pelas mudanças climáticas.", "o nicho ecológico de uma espécie constitui o local onde ela ocorre, como por exemplo uma floresta, um riacho ou um lago, e a alteração dos fatores físicos nesses ambientes pode provocar a extinção dessa espécie.", "a adaptação às novas condições ambientais ocorre devido às mutações neutras, as quais são mantidas por seleção natural.", "todas as espécies que ocorrem em um mesmo habitat competem por recursos e podem levar à extinção competidores mais fracos."]'::jsonb, 'A', 'Gabarito oficial: A. O nicho ecológico envolve recursos, condições e interações que permitem a sobrevivência e reprodução da espécie. Não equivale apenas ao local onde ela vive.' from public.exams where slug='pism-iii-2025-dia-1'

