insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 15, 'Biologia', 'O aborto espontâneo é um mecanismo natural, sem intervenção externa, no qual fetos inviáveis são perdidos durante a gestação. Uma das causas mais comuns de aborto espontâneo são as variações cromossômicas dos zigotos durante o processo de fertilização. A variação do número de cromossomos se dá', 'Redação adaptada para estudo; numeração e ordem das alternativas preservadas. Textos de apoio resumidos. Consulte a questão e os textos integrais no caderno oficial. Explicação autoral, não publicada pela banca. As 20 questões objetivas são comuns às quatro áreas; o link abre o caderno de Humanas. As discursivas não integram este cadastro.', null, '["pelo uso de preservativos impedindo a formação de cromossomos no zigoto.", "pelo aumento do número de espermatozoides que fertilizam o oócito.", "pela não separação de cromossomos normais durante a gametogênese.", "pela formação de zigotos oriunda da fusão de dois ou mais espermatozoides.", "pela fertilização de células somáticas do útero produzindo cromossomos extras."]'::jsonb, 'B/C', 'Gabarito oficial: B/C. O gabarito aceita B e C. A polispermia pode alterar conjuntos cromossômicos; a não disjunção pode gerar gametas com excesso ou falta de cromossomos, produzindo aneuploidias.' from public.exams where slug='pism-iii-2025-dia-1'

