insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 18, 'Matemática', 'F(x) e Q(x) são divisíveis por x−1. Na divisão de F por Q, o resto é R(x)=x³−x²+ax−9. Qual conjunto reúne as raízes de R?', 'Redação adaptada para estudo; numeração e ordem das alternativas preservadas. Textos de apoio resumidos. Consulte a questão e os textos integrais no caderno oficial. Explicação autoral, não publicada pela banca. As 20 questões objetivas são comuns às quatro áreas; o link abre o caderno de Humanas. As discursivas não integram este cadastro.', null, '["{−3,−1,3}", "{−i,3,i}", "{−3i,1,3i}", "{−9i,−1,9i}", "{−√3i,1,√3i}"]'::jsonb, 'C', 'Gabarito oficial: C. Como F e Q são divisíveis por x−1, R(1)=0. Logo a=9 e R(x)=(x−1)(x²+9). As raízes são 1, 3i e −3i.' from public.exams where slug='pism-iii-2025-dia-1'

