insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 20, 'Matemática', 'Sejam r a reta de equação y = mx+b, A e B os pontos em que essa reta intersecta as retas s1 : y = 3x e s2 : y = −x/5, respectivamente. O ponto M = (3, 1) é o ponto médio do segmento AB. As coordenadas do ponto em que a reta r intersecta o eixo das ordenadas é', 'Redação adaptada para estudo; numeração e ordem das alternativas preservadas. Textos de apoio resumidos. Consulte a questão e os textos integrais no caderno oficial. Explicação autoral, não publicada pela banca. As 20 questões objetivas são comuns às quatro áreas; o link abre o caderno de Humanas. As discursivas não integram este cadastro.', null, '["(0, −2)", "(0, 2)", "(0, 4)", "(0, 5)", "(0, 8)"]'::jsonb, 'C', 'Gabarito oficial: C. O ponto médio é (3,1). Se A pertence a y=3x e B a y=−x/5, obtemos A=(1,3) e B=(5,−1). A reta AB é y=−x+4, cruzando o eixo vertical em (0,4).' from public.exams where slug='pism-iii-2025-dia-1'

