insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 1, 'Física', 'Um termômetro infravermelho mede a radiação térmica emitida, cuja intensidade é modelada por I=εσT⁴. Qual condição pode afetar sua leitura?', 'Redação adaptada para estudo; numeração e ordem das alternativas preservadas. Textos de apoio resumidos. Consulte a questão e os textos integrais no caderno oficial. Explicação autoral, não publicada pela banca. As 20 questões objetivas são comuns às quatro áreas; o link abre o caderno de Humanas. As discursivas não integram este cadastro.', null, '["A intensidade se mede em graus Celsius.", "A temperatura pode ser medida através de qualquer vidro ou plástico sem perda de precisão.", "Só seres vivos podem ter a temperatura medida.", "O termômetro emite radiação que necessariamente provoca câncer.", "Um objeto quente próximo pode interferir na temperatura indicada."]'::jsonb, 'E', 'Gabarito oficial: E. A radiação emitida por um objeto quente próximo pode contaminar a medição, alterando a temperatura indicada pelo termômetro infravermelho.' from public.exams where slug='pism-iii-2025-dia-2'

