insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 2, 'Física', 'Fogões de indução são, uma alternativa ecológica ao fogão a gás convencional, pois funcionam com a indução de corrente elétrica no fundo da panela pela presença de uma bobina dentro do fogão. A bobina fica paralela ao fundo da panela e é ligada a uma fonte de corrente alternada. Entre a bobina e a panela, existe uma placa de vidro, de modo que a bobina não encosta na panela. Por simplicidade, considere que a bobina do fogão é formada por um solenoide de diâmetro D, conforme mostra a figura a seguir. O fundo da panela, neste caso, pode ser considerado como uma espira de uma volta. Para melhorar o projeto do conjunto fogão de indução/panela descrito acima, pensando em aumentar a eficiência no aquecimento da panela, sem aquecer o fogão, pode-se', 'Redação adaptada para estudo; numeração e ordem das alternativas preservadas. Textos de apoio resumidos. Consulte a questão e os textos integrais no caderno oficial. Explicação autoral, não publicada pela banca. As 20 questões objetivas são comuns às quatro áreas; o link abre o caderno de Humanas. As discursivas não integram este cadastro.', '/pism-iii-2025-dia-2-questao-2.png', '["aumentar a distância entre a panela e a bobina.", "aumentar o diâmetro D da bobina interna do fogão.", "utilizar apenas metais ferromagnéticos na construção da bobina interna.", "utilizar metais com maior resistividade na fabricação da panela.", "reduzir a frequência da fonte de corrente."]'::jsonb, 'D', 'Gabarito oficial: D. No modelo idealizado do enunciado, maior resistividade no fundo da panela aumenta a dissipação Joule para a corrente induzida considerada. A energia deve ser dissipada na panela, não na bobina.' from public.exams where slug='pism-iii-2025-dia-2'

