insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 3, 'Física', 'Um casal de irmãos gêmeos, Alice e Bob, têm à sua disposição duas naves espaciais que os levarão a um planeta distante recém descoberto. Em determinado instante, quando ambos possuíam a mesma idade, Alice parte em direção ao planeta. Bob fica ainda na Terra e só depois de certo tempo, viaja também. Considere as velocidades das naves altas o suficiente (próximas à velocidade da luz), e que ambos chegam juntos ao planeta. Nesse caso,', 'Redação adaptada para estudo; numeração e ordem das alternativas preservadas. Textos de apoio resumidos. Consulte a questão e os textos integrais no caderno oficial. Explicação autoral, não publicada pela banca. As 20 questões objetivas são comuns às quatro áreas; o link abre o caderno de Humanas. As discursivas não integram este cadastro.', null, '["a relatividade especial não permite distinguir qual dos dois será o mais velho ao fim da viagem.", "pode-se concluir que, ao fim da viagem, Alice será mais velha do que Bob.", "como ambos percorreram a mesma distância, eles chegarão com a mesma idade.", "os efeitos de dilatação temporal são detectados apenas no referencial de partida dos irmãos.", "os tempos gastos por Alice e Bob medidos no referencial da Terra são os mesmos para completar a viagem devido à dilatação temporal."]'::jsonb, 'B', 'Gabarito oficial: B. Para chegarem juntos, Bob percorre a mesma distância em menos tempo terrestre e, portanto, a maior velocidade. Seu tempo próprio acumulado é menor: ao final, Alice é mais velha.' from public.exams where slug='pism-iii-2025-dia-2'

