insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 4, 'Física', 'O efeito Doppler corresponde à alteração do comprimento de onda detectada por um observador quando uma fonte de ondas sonoras se desloca em relação ao observador. Este efeito não é somente restrito ao som. Ele também ocorre com a luz, sendo utilizado em astronomia e cosmologia observacional para estudar o universo em larga escala. E bem sabido que galáxias distantes estão se afastando de nós. Logo, a luz, no espectro visível, oriunda de uma determinada galáxia distante, ao ser detectada na Terra,', 'Redação adaptada para estudo; numeração e ordem das alternativas preservadas. Textos de apoio resumidos. Consulte a questão e os textos integrais no caderno oficial. Explicação autoral, não publicada pela banca. As 20 questões objetivas são comuns às quatro áreas; o link abre o caderno de Humanas. As discursivas não integram este cadastro.', null, '["não experimenta o efeito Doppler, que só é detectável no referencial da galáxia.", "sofre alteração na sua velocidade, pois há alteração no comprimento de onda.", "terá a energia dos seus fótons aumentada.", "não sofre mudança em sua frequência, que é uma grandeza absoluta.", "sofre um desvio para o vermelho (ou seja, aumento do comprimento de onda)."]'::jsonb, 'E', 'Gabarito oficial: E. A luz de uma galáxia que se afasta apresenta desvio para comprimentos de onda maiores, chamado desvio para o vermelho; no vácuo a velocidade da luz permanece c.' from public.exams where slug='pism-iii-2025-dia-2'

