insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 6, 'Química', 'Na produção de carbeto de cálcio: CaCO₃(s)→CaO(s)+CO₂(g), ΔH=+177,5 kJ/mol; depois CaO(s)+3C(grafita)→CaC₂(s)+CO(g). Qual afirmação está correta?', 'Redação adaptada para estudo; numeração e ordem das alternativas preservadas. Textos de apoio resumidos. Consulte a questão e os textos integrais no caderno oficial. Explicação autoral, não publicada pela banca. As 20 questões objetivas são comuns às quatro áreas; o link abre o caderno de Humanas. As discursivas não integram este cadastro.', null, '["a decomposição do carbonato de cálcio é acelerada pela diminuição da temperatura.", "a primeira e a segunda etapas envolvem reações de oxi-redução.", "em ambas as etapas, há produção de gás carbônico, que é prejudicial ao meio ambiente.", "na primeira etapa, há formação de um gás que, ao reagir com água, diminui o pH do meio.", "o calcário, quando em meio aquoso, tem a sua solubilidade alterada somente pelo pH."]'::jsonb, 'D', 'Gabarito oficial: D. A primeira reação libera CO₂. Dissolvido em água, esse gás estabelece equilíbrios associados à formação de ácido carbônico e à redução do pH.' from public.exams where slug='pism-iii-2025-dia-2'

