insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 7, 'Química', 'O esmalte contém hidroxiapatita. No equilíbrio Ca₅(PO₄)₃OH(s) ⇌ 5Ca²⁺(aq)+3PO₄³⁻(aq)+OH⁻(aq), a reação direta desmineraliza e a inversa remineraliza. Que condição favorece sua preservação?', 'Redação adaptada para estudo; numeração e ordem das alternativas preservadas. Textos de apoio resumidos. Consulte a questão e os textos integrais no caderno oficial. Explicação autoral, não publicada pela banca. As 20 questões objetivas são comuns às quatro áreas; o link abre o caderno de Humanas. As discursivas não integram este cadastro.', null, '["aumento da basicidade do meio em que ocorre a reação.", "diminuição da concentração de íons Ca2+.", "manutenção do equilíbrio pela retirada contínua dos íons.", "neutralização do íon OH−, tornando o meio mais básico.", "redução do pH da boca, tornando a saliva mais ácida."]'::jsonb, 'A', 'Gabarito oficial: A. Aumentar a basicidade fornece OH⁻ e favorece o deslocamento do equilíbrio para o sólido, ajudando a preservar a hidroxiapatita do esmalte.' from public.exams where slug='pism-iii-2025-dia-2'

