insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 8, 'Química', 'O etanol combustível (CH3CH2OH), popularmente chamado de “álcool de posto” faz parte da matriz energética brasileira e é considerado um biocombustível. Diferentes processos industriais podem ser utilizados para a obtenção de etanol combustível, mas o mais utilizado é o processo de primeira geração, que utiliza como matéria prima o suco da cana-de-açúcar. Sobre a produção de etanol, indique a alternativa CORRETA.', 'Redação adaptada para estudo; numeração e ordem das alternativas preservadas. Textos de apoio resumidos. Consulte a questão e os textos integrais no caderno oficial. Explicação autoral, não publicada pela banca. As 20 questões objetivas são comuns às quatro áreas; o link abre o caderno de Humanas. As discursivas não integram este cadastro.', null, '["A produção de álcool ocorre na etapa de produção do melado.", "Na etapa de fermentação ocorre a transformação dos lipídeos em etanol.", "O álcool é retirado da mistura bruta através de destilação.", "Na indústria da cana-de-açúcar o etanol é o único produto gerado.", "A cana-de-açúcar é a única fonte de produção de etanol."]'::jsonb, 'C', 'Gabarito oficial: C. A fermentação transforma açúcares em etanol; a destilação separa o álcool da mistura obtida, aproveitando diferenças de volatilidade.' from public.exams where slug='pism-iii-2025-dia-2'

