insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 9, 'Química', 'Observe a fórmula estrutural do metilfenidato. Qual afirmação sobre a molécula é correta?', 'Redação adaptada para estudo; numeração e ordem das alternativas preservadas. Textos de apoio resumidos. Consulte a questão e os textos integrais no caderno oficial. Explicação autoral, não publicada pela banca. As 20 questões objetivas são comuns às quatro áreas; o link abre o caderno de Humanas. As discursivas não integram este cadastro.', '/pism-iii-2025-dia-2-questao-9.png', '["Há três carbonos assimétricos.", "Sua fórmula molecular é C₁₄H₁₈NO₂.", "Apresenta amida, éster e anel aromático.", "Uma de suas funções orgânicas pode ser hidrolisada.", "Há quatro pares de elétrons π entre átomos de carbono."]'::jsonb, 'D', 'Gabarito oficial: D. O metilfenidato possui função éster, que pode sofrer hidrólise. Não possui função amida; seu nitrogênio integra uma amina.' from public.exams where slug='pism-iii-2025-dia-2'

