insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 10, 'Química', 'Para 2NO(g)+2H₂(g)→N₂(g)+2H₂O(g), a 1000 K, três experimentos apresentam [NO], [H₂] e velocidade inicial: (1,0; 0,5; 3,0×10⁴), (1,0; 1,0; 6,0×10⁴), (2,0; 0,5; 12,0×10⁴). Concentrações em mol/L e velocidade em mol/(L·s). Qual a lei de velocidade?', 'Redação adaptada para estudo; numeração e ordem das alternativas preservadas. Textos de apoio resumidos. Consulte a questão e os textos integrais no caderno oficial. Explicação autoral, não publicada pela banca. As 20 questões objetivas são comuns às quatro áreas; o link abre o caderno de Humanas. As discursivas não integram este cadastro.', null, '["v=k[NO]²[H₂]", "v=2k[NO][H₂]", "v=k[NO]²[H₂]²", "v=k[N₂][H₂O]²", "v=k[N₂][H₂O]²/([NO]²[H₂]²)"]'::jsonb, 'A', 'Gabarito oficial: A. Dobrar H₂, mantendo NO, dobra a velocidade: primeira ordem em H₂. Dobrar NO quadruplica a velocidade: segunda ordem em NO. Assim, v=k[NO]²[H₂].' from public.exams where slug='pism-iii-2025-dia-2'

