insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 11, 'Geografia', 'Uma notícia de maio de 2024 registra o reconhecimento da Palestina por Espanha, Noruega e Irlanda. Qual é sua condição junto à ONU no contexto da prova?', 'Redação adaptada para estudo; numeração e ordem das alternativas preservadas. Textos de apoio resumidos. Consulte a questão e os textos integrais no caderno oficial. Explicação autoral, não publicada pela banca. As 20 questões objetivas são comuns às quatro áreas; o link abre o caderno de Humanas. As discursivas não integram este cadastro.

Reportagem resumida. A questão se refere ao período do caderno de 2025.', null, '["não é reconhecida pela ONU.", "trata-se de um Estado antissemita.", "trata-se de Estado observador não membro.", "trata-se de Estado reconhecido apenas por não membros.", "trata-se de um membro da Organização das Nações e Povos Não Representados."]'::jsonb, 'C', 'Gabarito oficial: C. No contexto cobrado pela prova, a Palestina possui na ONU a condição de Estado observador não membro, diferente da condição de membro pleno.' from public.exams where slug='pism-iii-2025-dia-2'

