insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 12, 'Geografia', 'Em 2023, estimativas da ONU apontaram a Índia como o país mais populoso, superando a China. Qual fator das últimas décadas ajuda a explicar essa mudança?', 'Redação adaptada para estudo; numeração e ordem das alternativas preservadas. Textos de apoio resumidos. Consulte a questão e os textos integrais no caderno oficial. Explicação autoral, não publicada pela banca. As 20 questões objetivas são comuns às quatro áreas; o link abre o caderno de Humanas. As discursivas não integram este cadastro.

Dados do texto-base resumidos: Índia, cerca de 1,4286 bilhão; China, cerca de 1,4257 bilhão em 2023.', null, '["a emigração da China por motivos de perseguição política.", "a política de restrição ao número de filhos permitido por casal na China.", "a Índia completar o seu processo de transição demográfica há muitas décadas.", "o papel que a Índia tem ocupado como pólo de atração de imigrantes qualificados.", "a Índia implantar políticas de natalidade que incentivam o aumento das taxas de fecundidade."]'::jsonb, 'B', 'Gabarito oficial: B. A política chinesa de restrição de nascimentos reduziu a fecundidade por décadas, contribuindo para a mudança de posição populacional em relação à Índia.' from public.exams where slug='pism-iii-2025-dia-2'

