insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 13, 'Geografia', 'Um relatório da ONU de 2024 apontou avanço insuficiente das metas dos ODS, previstas para 2030. Que fator ajuda a explicar as dificuldades de implementação?', 'Redação adaptada para estudo; numeração e ordem das alternativas preservadas. Textos de apoio resumidos. Consulte a questão e os textos integrais no caderno oficial. Explicação autoral, não publicada pela banca. As 20 questões objetivas são comuns às quatro áreas; o link abre o caderno de Humanas. As discursivas não integram este cadastro.', null, '["as razões que levaram a elaboração dos ODS em 2015 não são mais um problema atualmente.", "os países europeus não conseguiram cumprir as metas estabelecidas porque a estes foram impostas medidas mais rigorosas.", "a desvalorização das commodities agrícolas prejudicou a capacidade dos países em desenvolvimento de tomar medidas em defesa do meio ambiente.", "o conjunto de medidas adotadas pelas empresas foi suficiente para a resolução dos problemas apontados, tornando desnecessária a ação dos Estados.", "os ODS subestimaram as assimetrias entre países emergentes e desenvolvidos na capacidade fiscal e política de implementar as medidas recomendadas."]'::jsonb, 'E', 'Gabarito oficial: E. Diferenças de recursos fiscais, capacidade institucional e poder político dificultam a implementação dos ODS e afetam desigualmente os países.' from public.exams where slug='pism-iii-2025-dia-2'

