insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 15, 'Geografia', 'Brasil, Índia, Alemanha e Japão propuseram ampliar o Conselho de Segurança da ONU. Que fator ajuda a explicar a oposição chinesa à proposta?', 'Redação adaptada para estudo; numeração e ordem das alternativas preservadas. Textos de apoio resumidos. Consulte a questão e os textos integrais no caderno oficial. Explicação autoral, não publicada pela banca. As 20 questões objetivas são comuns às quatro áreas; o link abre o caderno de Humanas. As discursivas não integram este cadastro.

O texto-base aborda a proposta do G4 e rivalidades geopolíticas entre candidatos e membros permanentes.', null, '["Rússia têm conflitos militares com a Alemanha desde o final da Segunda Guerra Mundial.", "China tem litígios fronteiriços com a Índia e uma rivalidade histórica com o Japão.", "Rússia e China disputam com a Índia a liderança da tecnologia do 5G aplicado à indústria bélica.", "Rússia e China impõem restrições aos quatro países devido ao não cumprimento de acordos ambientais.", "Rússia e China discordam dos quatro países devido à posição destes frente ao conflito PalestinaIsrael. HISTORIA - OBJETIVAS"]'::jsonb, 'B', 'Gabarito oficial: B. A China possui litígios fronteiriços com a Índia e rivalidades históricas com o Japão, fatores que ajudam a explicar a resistência à proposta do G4.' from public.exams where slug='pism-iii-2025-dia-2'

