insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 17, 'História', 'Cartazes da Ação Integralista Brasileira e do Partido Comunista ilustram a Era Vargas. Qual alternativa interpreta a atuação desses movimentos?', 'Redação adaptada para estudo; numeração e ordem das alternativas preservadas. Textos de apoio resumidos. Consulte a questão e os textos integrais no caderno oficial. Explicação autoral, não publicada pela banca. As 20 questões objetivas são comuns às quatro áreas; o link abre o caderno de Humanas. As discursivas não integram este cadastro.

Descrição das fontes: propaganda integralista e comunista, representando movimentos de orientação ideológica distinta. Imagens no caderno oficial.', null, '["A trajetória dos dois movimentos foi marcada por grande apoio popular baseado em valores tradicionais, defesa da ordem e da disciplina, representados pela tríade Deus, Pátria e Família.", "A atuação do Partido Comunista por meio da Aliança Nacional Libertadora foi vitoriosa na Intentona Comunista, conseguindo apoio de Vargas em contraposição às pressões dos Integralistas.", "Do ponto de vista econômico ambos os movimentos apoiavam pautas liberais, como a modernização econômica e a criação de grandes empresas estatais, bem como políticas intervencionistas e planejadas.", "Representam dois importantes movimentos políticos do período republicano brasileiro e caracterizavam-se por fortes influências do cenário internacional, tais como o ideário fascista e a expansão socialista da União Soviética.", "O Partido Comunista Brasileiro que integrou a Aliança Nacional Libertadora e os Integralistas por meio da Ação Integralista Brasileira receberam apoio do governo Vargas para a construção de suas pautas trabalhistas."]'::jsonb, 'D', 'Gabarito oficial: D. Integralismo e comunismo recebem influências internacionais distintas: fascismo e expansão do socialismo soviético, respectivamente. Não defendem a mesma pauta.' from public.exams where slug='pism-iii-2025-dia-2'

