insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 18, 'História', 'Uma reportagem reúne relatos de vigilância, censura e perseguição de professores depois do golpe de 1964. Qual afirmação corresponde às características da ditadura civil-militar?', 'Redação adaptada para estudo; numeração e ordem das alternativas preservadas. Textos de apoio resumidos. Consulte a questão e os textos integrais no caderno oficial. Explicação autoral, não publicada pela banca. As 20 questões objetivas são comuns às quatro áreas; o link abre o caderno de Humanas. As discursivas não integram este cadastro.', null, '["A censura prévia era organizada por uma equipe de professores qualificados de cada escola que avaliavam o conteúdo dos livros didáticos e outras publicações a serviço do governo.", "O autoritarismo era marcado pela tortura e outras formas de violências que tinham como objetivo controlar, punir e desencorajar as manifestações dos professores contra o governo.", "A centralização política era própria dos governos militares que respeitavam a autonomia e liberdade ilimitada dos professores, mas vigiavam e perseguiam as escolas e os jornais estudantis.", "A supressão dos direitos civis e constitucionais era mantida para evitar a propaganda de novas ideologias, autorizando a discussão nas escolas, mas instalando a desconfiança entre os professores.", "A tortura era uma prática exercida pelas instituições militares que deviam incentivar a participação dos professores sem limitações, principalmente, aos temas políticos."]'::jsonb, 'B', 'Gabarito oficial: B. Censura, vigilância, perseguição e violência foram instrumentos de repressão e de controle dos professores durante a ditadura civil-militar.' from public.exams where slug='pism-iii-2025-dia-2'

