insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 16, 'Matemática', 'Na figura, r: −x+y=2 e s: x+2y=16. A reta t: y=ax+b passa pelo mesmo ponto de interseção, no primeiro quadrante, e tem inclinação entre as de r e s. Que limites devem satisfazer a e b?', 'Redação adaptada para estudo; numeração e ordem das alternativas preservadas. Textos de apoio resumidos. Consulte a questão e os textos integrais no caderno oficial. Explicação autoral, não publicada pela banca. As 20 questões objetivas são comuns às quatro áreas; o link abre o caderno de Humanas. As discursivas não integram este cadastro.', '/pism-iii-2026-dia-1-questao-16.png', '["−1/2 < a < 1 e 2 < b < 8", "−1 < a < 1 e 2 < b < 8", "2 < a < 8 e −1/2 < b < 1", "2 < a < 8 e −1 < b < 1", "−1 < a < 1 e 2 < b < 16"]'::jsonb, 'A', 'Gabarito oficial: A. As retas r e s se encontram em (4,6): y=x+2 e x+2y=16. Para t passar por esse ponto, b=6−4a. Sua inclinação está entre −1/2 e 1; assim, −1/2<a<1 e 2<b<8.' from public.exams where slug='pism-iii-2026-dia-1'

