insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 17, 'Matemática', 'Ana paga R$15 por 2 bombons de uva, 1 de morango e 1 de ameixa. Beatriz paga R$8 por 1 de uva e 1 de ameixa. Carla paga R$13 por 2 de morango e 1 de ameixa. Quanto Denise paga por 1 de uva, 1 de morango e 2 de ameixa?', 'Redação adaptada para estudo; numeração e ordem das alternativas preservadas. Textos de apoio resumidos. Consulte a questão e os textos integrais no caderno oficial. Explicação autoral, não publicada pela banca. As 20 questões objetivas são comuns às quatro áreas; o link abre o caderno de Humanas. As discursivas não integram este cadastro.', null, '["R$12", "R$15", "R$16", "R$17", "R$21"]'::jsonb, 'D', 'Gabarito oficial: D. Se u, m e a são os preços, 2u+m+a=15, u+a=8 e 2m+a=13. Resultam u=3, m=4 e a=5. Denise paga u+m+2a = 3+4+10 = 17 reais.' from public.exams where slug='pism-iii-2026-dia-1'

