insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 18, 'Matemática', 'Se x=2^(3+log₂5), y=3^(2−log₃5) e z=6^[(log₉4)(log₆3)], qual é o valor de xyz?', 'Redação adaptada para estudo; numeração e ordem das alternativas preservadas. Textos de apoio resumidos. Consulte a questão e os textos integrais no caderno oficial. Explicação autoral, não publicada pela banca. As 20 questões objetivas são comuns às quatro áreas; o link abre o caderno de Humanas. As discursivas não integram este cadastro.', null, '["52", "72", "144", "156·6^(log₉4)", "216·6^(log₉4)"]'::jsonb, 'C', 'Gabarito oficial: C. Pelas propriedades de logaritmos, x=2³·5=40 e y=3²/5=9/5. Como (log₉4)(log₆3)=log₆2, z=2. Logo xyz=40·(9/5)·2=144.' from public.exams where slug='pism-iii-2026-dia-1'

